using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B3RepairLodApply {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 edit required");string root=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string h=root+"/SourceAssets/B3_StructureRepair/",old=root+"/SourceAssets/B3_FullFloor/";var plans=JArray.Parse(File.ReadAllText(old+"lod_plan.json")).Concat(JArray.Parse(File.ReadAllText(h+"lod_plan.json"))).ToArray();var cat=JArray.Parse(File.ReadAllText(old+"lod_catalog.json")).Concat(JArray.Parse(File.ReadAllText(h+"lod_catalog.json"))).ToArray();var mods=JArray.Parse(File.ReadAllText(old+"lod_models.json")).Concat(JArray.Parse(File.ReadAllText(h+"lod_models.json"))).ToArray();var added=new List<string>();foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.GetComponent<MeshFilter>()&&!r.GetComponent<LODGroup>()&&!r.name.StartsWith("Distance_LOD"))){var asset=AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh);var p=plans.FirstOrDefault(p=>(string)p["asset"]==asset);if(p==null)continue;var lods=new LOD[3];lods[0]=new LOD(.18f,new Renderer[]{r});for(int level=1;level<3;level++){string n=(string)p["name"]+"_LOD"+level;var c=cat.Single(c=>(string)c["name"]==n);var mod=mods.Single(m=>(string)m["name"]==n);if((int)c["degenerate"]!=0||(float)c["boundsError"]>.03f)throw new Exception("Invalid LOD "+n);var src=AssetDatabase.LoadAssetAtPath<GameObject>((string)c["path"]).GetComponentsInChildren<MeshFilter>().Single();var g=new GameObject("Distance_LOD"+level);g.transform.SetParent(r.transform,false);g.AddComponent<MeshFilter>().sharedMesh=src.sharedMesh;var nr=g.AddComponent<MeshRenderer>();nr.sharedMaterials=mod["slots"].Select(i=>r.sharedMaterials[(int)i]).ToArray();nr.shadowCastingMode=r.shadowCastingMode;nr.receiveShadows=r.receiveShadows;nr.lightProbeUsage=r.lightProbeUsage;nr.reflectionProbeUsage=r.reflectionProbeUsage;nr.renderingLayerMask=r.renderingLayerMask;lods[level]=new LOD(level==1?.055f:0,new Renderer[]{nr});}var group=r.gameObject.AddComponent<LODGroup>();group.fadeMode=LODFadeMode.CrossFade;group.animateCrossFading=true;group.SetLODs(lods);group.RecalculateBounds();added.Add(r.name);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(root+"/Docs/Review/2026-11-09_B3_StructureRepair/lod_apply.json",JsonConvert.SerializeObject(new{groups=added.Count,names=added},Formatting.Indented));return new{groups=added.Count};}
}
